css:
.sl-gallery-interactive-map { padding-block: clamp(3rem, 6vw, 5rem); padding-inline: clamp(1rem, 3vw, 2rem); background-color: var(--smartlearn-bg); font-family: var(--smartlearn-body-font, system-ui, sans-serif); }
.sl-gallery-interactive-map .sl-container { max-width: 1140px; width: 100%; margin-inline: auto; }
.sl-gallery-interactive-map .sl-header { text-align: center; margin-bottom: 2.5rem; }
.sl-gallery-interactive-map .sl-section-title { font-family: var(--smartlearn-heading-font, inherit); font-size: clamp(1.75rem, 3.5vw, 2.25rem); font-weight: 700; color: var(--smartlearn-text); margin: 0 0 0.5rem; }
.sl-gallery-interactive-map .sl-section-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); margin: 0; }
.sl-gallery-interactive-map .sl-map-container { position: relative; max-width: 1000px; margin-inline: auto; border-radius: var(--smartlearn-radius, 1rem); overflow: hidden; border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); box-shadow: 0 15px 30px rgba(0, 0, 0, 0.08); background-color: var(--smartlearn-card-bg); }
.sl-gallery-interactive-map .sl-map-stage { position: relative; width: 100%; }
.sl-gallery-interactive-map .sl-map-base { width: 100%; display: block; object-fit: cover; aspect-ratio: 16/9; }
.sl-gallery-interactive-map .sl-map-pin { position: absolute; width: 44px; height: 44px; background: transparent; border: none; cursor: pointer; display: flex; align-items: center; justify-content: center; transform: translate(-50%, -50%); z-index: 10; padding: 0; }
.sl-gallery-interactive-map .sl-map-pin:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; border-radius: 50%; }
.sl-gallery-interactive-map .sl-pin-dot { width: 26px; height: 26px; background-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); font-size: 0.75rem; font-weight: 700; border-radius: 50%; box-shadow: 0 2px 6px rgba(0, 0, 0, 0.35); border: 2px solid #ffffff; z-index: 2; display: flex; align-items: center; justify-content: center; transition: transform 0.2s ease; }
.sl-gallery-interactive-map .sl-map-pin:hover .sl-pin-dot, .sl-gallery-interactive-map .sl-pin-active .sl-pin-dot { transform: scale(1.2); }
.sl-gallery-interactive-map .sl-pin-pulse { position: absolute; width: 32px; height: 32px; background-color: var(--smartlearn-primary); border-radius: 50%; opacity: 0.45; z-index: 1; animation: sl-gallery-map-pulse 2s infinite; }
@keyframes sl-gallery-map-pulse { 0% { transform: scale(1); opacity: 0.65; } 100% { transform: scale(2.1); opacity: 0; } }
.sl-gallery-interactive-map .sl-map-info-panel { position: absolute; bottom: 1.5rem; inset-inline-start: 1.5rem; background: var(--smartlearn-bg); padding: 1.15rem 1.35rem; border-radius: var(--smartlearn-radius, 0.75rem); box-shadow: 0 10px 25px rgba(0, 0, 0, 0.18); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); max-width: 300px; display: none; gap: 0.875rem; align-items: flex-start; z-index: 20; }
.sl-gallery-interactive-map .sl-map-info-panel.sl-show { display: flex; }
.sl-gallery-interactive-map .sl-info-num { width: 26px; height: 26px; border-radius: 50%; flex-shrink: 0; background-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); font-size: 0.75rem; font-weight: 700; display: inline-flex; align-items: center; justify-content: center; margin-top: 0.1rem; }
.sl-gallery-interactive-map .sl-info-title { font-family: var(--smartlearn-heading-font, inherit); font-size: 1.05rem; font-weight: 700; color: var(--smartlearn-text); margin: 0 0 0.35rem; }
.sl-gallery-interactive-map .sl-info-desc { font-size: 0.875rem; color: var(--smartlearn-text-muted); margin: 0; line-height: 1.5; }
@media (max-width: 767px) {
  .sl-gallery-interactive-map .sl-map-base { aspect-ratio: 4/3; }
  .sl-gallery-interactive-map .sl-map-info-panel { position: static; max-width: 100%; box-shadow: none; border-radius: 0; border: none; border-top: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); display: flex; }
  .sl-gallery-interactive-map .sl-map-info-panel.sl-show { background-color: color-mix(in srgb, var(--smartlearn-primary) 8%, var(--smartlearn-card-bg)); }
}
@media (prefers-reduced-motion: reduce) { .sl-gallery-interactive-map .sl-pin-pulse { animation: none; display: none; } .sl-gallery-interactive-map .sl-pin-dot { transition: none; } }

