(function() {
  var init = function() {
    document.querySelectorAll('.sl-gallery-interactive-map').forEach(function(root, sIdx) {
      if (root.dataset.slInit === '1') return;
      root.dataset.slInit = '1';
      var uid = 'sl-gmap-' + sIdx + '-' + Math.random().toString(36).slice(2, 7);
      var pins = Array.prototype.slice.call(root.querySelectorAll('.sl-map-pin'));
      var panels = Array.prototype.slice.call(root.querySelectorAll('.sl-map-info-panel'));
      if (!pins.length) return;
      pins.forEach(function(pin, pIdx) {
        var targetKey = pin.getAttribute('data-target');
        var panel = panels.find(function(p) { return p.getAttribute('data-panel') === targetKey; });
        var pinId = uid + '-pin-' + pIdx;
        pin.id = pinId;
        if (panel) {
          var panelId = uid + '-panel-' + pIdx;
          panel.id = panelId;
          pin.setAttribute('aria-controls', panelId);
          panel.setAttribute('aria-labelledby', pinId);
        }
        pin.addEventListener('click', function() {
          pins.forEach(function(p) {
            var active = p === pin;
            p.classList.toggle('sl-pin-active', active);
            p.setAttribute('aria-expanded', active ? 'true' : 'false');
          });
          panels.forEach(function(pnl) {
            pnl.classList.toggle('sl-show', pnl.getAttribute('data-panel') === targetKey);
          });
        });
        pin.addEventListener('keydown', function(e) {
          if (e.key === 'Escape') {
            pin.blur();
          }
        });
      });
    });
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
